{"content":"# Adaptive Rejection Sampling (ARS) for log-concave densities
# Reference: Gilks, W. R., & Wild, P. (1992). Adaptive rejection sampling for
#   Gibbs sampling. Applied Statistics, 41(2), 337-348.
#
# Design: modular set of auxiliary (.ars_*) helpers, each implementing one
# discrete task, plus the primary user-facing `ars` function and a `test`
# function that checks samples against known truth.

# ---------------------------------------------------------------------------
# 1. Log-density evaluation
# ---------------------------------------------------------------------------

# Evaluate h(x) = log g(x) safely (vectorized).
# Returns -Inf where g(x) <= 0 (outside support / zero density), NaN/Inf g
# that is not finite-positive also maps to -Inf; NA input maps to NA_real_.
.ars_log_density <- function(x, g, ...) {
  x <- as.numeric(x)
  dens <- g(x, ...)
  if (length(dens) != length(x)) {
    stop("Density function 'g' must be vectorized: g(x) must return one value per input element.")
  }
  h <- rep(-Inf, length(x))
  ok <- !is.na(dens) & is.finite(dens) & dens > 0
  h[ok] <- log(dens[ok])
  h[is.na(dens) | is.na(x)] <- NA_real_
  h
}

# Numerical first derivative of h via central differences (vectorized loop).
# One-sided differences are used when a shifted point leaves (a, b).
.ars_log_deriv <- function(x, g, a = -Inf, b = Inf, ...) {
  x <- as.numeric(x)
  vapply(x, function(xi) {
    if (!is.finite(xi)) return(NA_real_)
    eps <- sqrt(.Machine$double.eps) * max(1, abs(xi))
    x_hi <- xi + eps
    x_lo <- xi - eps
    hi_in <- x_hi < b
    lo_in <- x_lo > a
    h0 <- .ars_log_density(xi, g, ...)
    if (!is.finite(h0)) return(NA_real_)
    if (hi_in && lo_in) {
      h_hi <- .ars_log_density(x_hi, g, ...)
      h_lo <- .ars_log_density(x_lo, g, ...)
      if (!is.finite(h_hi) || !is.finite(h_lo)) {
        # Fall back to one-sided using whichever side is finite.
        if (is.finite(h_hi)) return((h_hi - h0) / eps)
        if (is.finite(h_lo)) return((h0 - h_lo) / eps)
        return(NA_real_)
      }
      (h_hi - h_lo) / (2 * eps)
    } else if (hi_in) {
      h_hi <- .ars_log_density(x_hi, g, ...)
      if (!is.finite(h_hi)) return(NA_real_)
      (h_hi - h0) / eps
    } else if (lo_in) {
      h_lo <- .ars_log_density(x_lo, g, ...)
      if (!is.finite(h_lo)) return(NA_real_)
      (h0 - h_lo) / eps
    } else {
      NA_real_
    }
  }, numeric(1))
}

# ---------------------------------------------------------------------------
# 2. Input validation
# ---------------------------------------------------------------------------

.ars_validate_inputs <- function(n, g, a, b, x0) {
  if (length(n) != 1 || is.na(n) || !is.finite(n) || floor(n) != n || n <= 0) {
    stop("'n' must be a single positive integer (number of points to sample).")
  }
  if (!is.function(g)) {
    stop("'g' must be a function computing the (possibly unnormalized) density in vectorized fashion, e.g. function(x) dnorm(x).")
  }
  # g must accept a numeric vector and return a numeric vector of same length.
  probe <- tryCatch(g(c(0, 1)), error = function(e) e)
  if (inherits(probe, "error")) {
    # g(0), g(1) may fail on restricted domains; try a generic probe instead.
    probe2 <- tryCatch(g(c(0.5, 0.6)), error = function(e) e)
    if (inherits(probe2, "error")) {
      stop("'g' must be a vectorized density function of a numeric vector: ", conditionMessage(probe))
    }
  } else {
    if (!is.numeric(probe) || length(probe) != 2) {
      stop("Density function 'g' must be vectorized: g(c(0,1)) must return a numeric vector of length 2.")
    }
  }
  if (length(a) != 1 || length(b) != 1 || !is.numeric(a) || !is.numeric(b) ||
      is.na(a) || is.na(b) || !(a < b)) {
    stop("Domain bounds must satisfy a < b with numeric (possibly infinite) 'a' and 'b'.")
  }
  if (!is.null(x0)) {
    x0 <- as.numeric(x0)
    if (any(!is.finite(x0)) || any(is.na(x0))) {
      stop("Starting abscissae 'x0' must be finite numbers strictly inside (a, b).")
    }
    if (any(x0 <= a) || any(x0 >= b)) {
      stop("Starting abscissae 'x0' must lie strictly inside (a, b).")
    }
    if (length(x0) < 2) {
      stop("At least two starting abscissae 'x0' are required.")
    }
    if (anyDuplicated(x0)) {
      stop("Starting abscissae 'x0' must be distinct.")
    }
  }
  invisible(TRUE)
}

# ---------------------------------------------------------------------------
# 3. Starting abscissae
# ---------------------------------------------------------------------------

# Candidate grids used when the user does not supply x0.
.ars_default_grids <- function(a, b) {
  grids <- list()
  if (is.finite(a) && is.finite(b)) {
    m <- (a + b) / 2
    s <- (b - a)
    grids <- list(
      seq(a + 0.1 * s, b - 0.1 * s, length.out = 4),
      seq(a + 0.25 * s, b - 0.25 * s, length.out = 3),
      c(m - 0.05 * s, m + 0.05 * s)
    )
  } else if (is.finite(a)) {
    grids <- list(
      a + c(0.5, 1, 2, 4),
      a + c(0.1, 0.5, 1, 2),
      a + c(1, 2, 5, 10)
    )
  } else if (is.finite(b)) {
    grids <- list(
      b - c(4, 2, 1, 0.5),
      b - c(2, 1, 0.5, 0.1),
      b - c(10, 5, 2, 1)
    )
  } else {
    grids <- list(
      c(-4, -1, 1, 4),
      c(-2, -0.5, 0.5, 2),
      c(-1, -0.25, 0.25, 1)
    )
  }
  grids
}

# Pick / validate the initial abscissae. Returns sorted x with finite h and
# finite derivatives and an integrable envelope, or stops with guidance.
.ars_init_abscissae <- function(g, a, b, x0, ...) {
  if (!is.null(x0)) {
    x <- sort(as.numeric(x0))
    h <- .ars_log_density(x, g, ...)
    if (any(!is.finite(h))) {
      stop("Density 'g' must be strictly positive and finite at all starting abscissae 'x0'.")
    }
    dh <- .ars_log_deriv(x, g, a, b, ...)
    if (any(!is.finite(dh))) {
      stop("Could not compute a finite derivative of log g at 'x0'; choose starting points where the density is smooth and positive.")
    }
    .ars_check_brackets_mode(x, dh, a, b)
    return(list(x = x, h = h, dh = dh))
  }
  for (cand in .ars_default_grids(a, b)) {
    cand <- cand[cand > a & cand < b]
    if (length(cand) < 2) next
    h <- .ars_log_density(cand, g, ...)
    keep <- is.finite(h)
    if (sum(keep) < 2) next
    cand <- cand[keep]; h <- h[keep]
    dh <- .ars_log_deriv(cand, g, a, b, ...)
    keep2 <- is.finite(dh)
    if (sum(keep2) < 2) next
    cand <- cand[keep2]; h <- h[keep2]; dh <- dh[keep2]
    if (!.ars_brackets_mode(dh)) next
    # Integrability: leftmost slope > 0 (or finite left bound),
    # rightmost slope < 0 (or finite right bound).
    if (!is.finite(a) && dh[1] <= 0) next
    if (!is.finite(b) && dh[length(dh)] >= 0) next
    return(list(x = cand, h = h, dh = dh))
  }
  stop("Could not find starting abscissae bracketing the mode with an integrable envelope; please supply 'x0' (at least two points spanning the mode, where g is positive).")
}

.ars_brackets_mode <- function(dh) {
  any(dh > 0) && any(dh < 0)
}

.ars_check_brackets_mode <- function(x, dh, a, b) {
  if (!.ars_brackets_mode(dh)) {
    warning("Starting abscissae do not bracket the mode (derivatives of log g do not change sign); sampling may fail or be inefficient. Consider 'x0' values spanning the mode.")
  }
  invisible(TRUE)
}

# ---------------------------------------------------------------------------
# 4. Upper / lower hulls and envelope
# ---------------------------------------------------------------------------

# Intersection abscissa z_j of tangents at x_j and x_{j+1}:
#   z = (h_{j+1} - h_j - x_{j+1} dh_{j+1} + x_j dh_j) / (dh_j - dh_{j+1})
# Falls back to the midpoint for (numerically) parallel tangents.
.ars_tangent_intersections <- function(x, h, dh) {
  k <- length(x)
  if (k < 2) stop("Need at least two abscissae.")
  z <- numeric(k - 1)
  for (j in seq_len(k - 1)) {
    denom <- dh[j] - dh[j + 1]
    if (abs(denom) < .Machine$double.eps * max(1, abs(dh[j]), abs(dh[j + 1]))) {
      z[j] <- (x[j] + x[j + 1]) / 2
    } else {
      z[j] <- (h[j + 1] - h[j] - x[j + 1] * dh[j + 1] + x[j] * dh[j]) / denom
    }
  }
  z
}

# Upper hull u(x) = min of neighboring tangents (Gilks & Wild eq. 5).
.ars_upper_hull <- function(x_eval, x, h, dh, z) {
  vapply(x_eval, function(xe) {
    j <- findInterval(xe, z) + 1  # segment index 1..k
    j <- min(max(j, 1), length(x))
    h[j] + dh[j] * (xe - x[j])
  }, numeric(1))
}

# Lower hull l(x): chord between bracketing abscissae, -Inf outside [x_1, x_k].
.ars_lower_hull <- function(x_eval, x, h) {
  k <- length(x)
  vapply(x_eval, function(xe) {
    if (xe < x[1] || xe > x[k]) return(-Inf)
    j <- findInterval(xe, x)
    j <- min(max(j, 1), k - 1)
    if (xe == x[k]) return(h[k])
    w <- (xe - x[j]) / (x[j + 1] - x[j])
    (1 - w) * h[j] + w * h[j + 1]
  }, numeric(1))
}

# Log-concavity check: a log-concave h must lie everywhere below its tangents.
# Called whenever h(x*) is evaluated against the current upper hull.
.ars_check_logconcavity <- function(x_new, h_new, x, h, dh, z, tol = 1e-8) {
  u_new <- .ars_upper_hull(x_new, x, h, dh, z)
  bad <- is.finite(h_new) & is.finite(u_new) & (h_new > u_new + tol * max(1, abs(u_new)))
  if (any(bad)) {
    stop("Density does not appear to be log-concave: log g(x*) lies above its tangent upper bound at x* = ",
         paste(round(x_new[bad], 6), collapse = ", "))
  }
  invisible(TRUE)
}

# Envelope parameters: k tangent segments on intervals [L_j, R_j] intersected
# with [a, b]; each exp(u) piece is exp(alpha_j + beta_j * x) with weight w_j.
.ars_envelope_params <- function(x, h, dh, z, a, b) {
  k <- length(x)
  L <- c(a, z)
  R <- c(z, b)
  L <- pmax(L, a); R <- pmin(R, b)
  alpha <- h - dh * x
  beta <- dh
  w <- numeric(k)
  for (j in seq_len(k)) {
    if (!(L[j] < R[j])) next
    lo <- L[j]; hi <- R[j]
    bj <- beta[j]; aj <- alpha[j]
    if (abs(bj) < 1e-12) {
      w[j] <- exp(aj) * (hi - lo)
    } else {
      # Piecewise-exponential integral, evaluated in a stable order.
      if (is.finite(lo) && is.finite(hi)) {
        w[j] <- exp(aj) / bj * (exp(bj * hi) - exp(bj * lo))
      } else if (!is.finite(lo)) {
        # bj must be > 0 for convergence.
        if (bj <= 0) next
        w[j] <- exp(aj + bj * hi) / bj
      } else {
        # hi == +Inf; bj must be < 0.
        if (bj >= 0) next
        w[j] <- -exp(aj + bj * lo) / bj
      }
    }
    if (!is.finite(w[j]) || w[j] < 0) w[j] <- 0
  }
  if (all(w <= 0) || sum(w) <= 0 || !is.finite(sum(w))) {
    stop("Envelope is not integrable with the current abscissae (tails do not decay). Supply 'x0' spanning the mode so the leftmost log-density slope is positive and the rightmost is negative.")
  }
  list(L = L, R = R, alpha = alpha, beta = beta, w = w, total = sum(w))
}

# Draw m points from the normalized envelope s(x) propto exp(u(x)).
.ars_sample_from_envelope <- function(m, env) {
  probs <- env$w / env$total
  # Guard against tiny negative/NA weights from roundoff.
  probs[!is.finite(probs)] <- 0
  segs <- sample.int(length(probs), size = m, replace = TRUE, prob = probs)
  out <- numeric(m)
  for (j in unique(segs)) {
    idx <- which(segs == j)
    nj <- length(idx)
    lo <- env$L[j]; hi <- env$R[j]
    bj <- env$beta[j]; aj <- env$alpha[j]
    if (abs(bj) < 1e-12) {
      out[idx] <- runif(nj, min = lo, max = hi)
    } else if (!is.finite(lo)) {
      # Truncated-from-above exponential tail: x = hi + E/bj reflected.
      out[idx] <- hi + rexp(nj, rate = bj) * -1 * -1  # = hi - E/bj, bj > 0
      out[idx] <- hi - rexp(nj, rate = bj)
    } else if (!is.finite(hi)) {
      # x = lo + E/|bj|, bj < 0.
      out[idx] <- lo + rexp(nj, rate = -bj)
    } else {
      # Finite interval with slope: invert the CDF.
      u <- runif(nj)
      c_lo <- exp(bj * lo); c_hi <- exp(bj * hi)
      out[idx] <- log(c_lo + u * (c_hi - c_lo)) / bj
    }
  }
  out
}

# Insert a rejected point, keeping x sorted; re-checks derivative
# monotonicity (a necessary condition of log-concavity).
.ars_insert_point <- function(x_new, h_new, dh_new, x, h, dh) {
  ord <- order(c(x, x_new))
  x2 <- c(x, x_new)[ord]
  h2 <- c(h, h_new)[ord]
  dh2 <- c(dh, dh_new)[ord]
  d_dh <- diff(dh2)
  if (any(d_dh > 1e-6 * pmax(1, abs(dh2[-1]), abs(dh2[-length(dh2)])))) {
    stop("Density does not appear to be log-concave: derivatives of log g are not non-increasing in x.")
  }
  list(x = x2, h = h2, dh = dh2)
}

# ---------------------------------------------------------------------------
# 5. Primary sampler
# ---------------------------------------------------------------------------

#' Adaptive Rejection Sampling for log-concave densities
#'
#' @param n number of points to sample (single positive integer).
#' @param g function computing the (possibly unnormalized) density in
#'   vectorized fashion: \code{g(x)} must return one non-negative value per
#'   element of numeric vector \code{x} (e.g. \code{function(x) dnorm(x)}).
#' @param ... extra arguments passed to \code{g}.
#' @param a,b domain bounds (numeric scalars, possibly infinite) with a < b.
#' @param x0 optional starting abscissae (at least two distinct finite values
#'   strictly inside (a, b) where g is positive); chosen automatically if NULL.
#'
#' @return Numeric vector of length \code{n} with draws from the density
#'   proportional to \code{g} on (a, b).
#' @references Gilks, W. R., & Wild, P. (1992). Adaptive rejection sampling
#'   for Gibbs sampling. Applied Statistics, 41(2), 337-348.
#' @export
ars <- function(n, g, ..., a = -Inf, b = Inf, x0 = NULL) {
  .ars_validate_inputs(n, g, a, b, x0)
  n <- as.integer(n)

  init <- .ars_init_abscissae(g, a, b, x0, ...)
  x <- init$x; h <- init$h; dh <- init$dh

  samples <- numeric(n)
  n_accept <- 0L
  # Safety cap on total envelope draws (rejections + acceptances).
  max_draws <- 100L * n + 1000L
  n_draws <- 0L

  while (n_accept < n) {
    z <- .ars_tangent_intersections(x, h, dh)
    # Hull knots must be ordered; disorder signals non-concavity.
    if (any(diff(z) <= 0)) {
      stop("Density does not appear to be log-concave: tangent intersection points are not ordered.")
    }
    env <- .ars_envelope_params(x, h, dh, z, a, b)

    # Draw in batches for efficiency, but never beyond what is needed.
    batch <- min(500L, n - n_accept, max(1L, as.integer(1.5 * (n - n_accept)) + 10L))
    x_star <- .ars_sample_from_envelope(batch, env)
    n_draws <- n_draws + batch
    if (n_draws > max_draws) {
      stop("Sampler failed to accept ", n, " points within ", max_draws,
           " draws; the envelope may be far from the target (check log-concavity and starting values).")
    }

    u_star <- .ars_upper_hull(x_star, x, h, dh, z)
    l_star <- .ars_lower_hull(x_star, x, h)
    w <- runif(batch)

    # Squeeze test first (accept without evaluating g).
    squeeze_ok <- (w <= exp(l_star - u_star))
    need_eval <- which(!squeeze_ok)
    accept <- rep(FALSE, batch)
    accept[squeeze_ok] <- TRUE

    if (length(need_eval) > 0) {
      h_star <- .ars_log_density(x_star[need_eval], g, ...)
      if (any(is.na(h_star))) {
        stop("Density function 'g' returned NA/NaN; it must return non-negative numeric values.")
      }
      # --- Log-concavity check (Gilks & Wild): h must stay below tangents.
      .ars_check_logconcavity(x_star[need_eval], h_star, x, h, dh, z)

      accept[need_eval] <- (w[need_eval] <= exp(h_star - u_star[need_eval]))

      # Rejected points with finite h refine the hulls (adaptive step).
      rejected <- need_eval[!accept[need_eval]]
      for (r in rejected) {
        xr <- x_star[r]
        hr <- .ars_log_density(xr, g, ...)
        if (!is.finite(hr)) next  # zero-density point: reject, do not add
        dhr <- .ars_log_deriv(xr, g, a, b, ...)
        if (!is.finite(dhr)) next
        ins <- .ars_insert_point(xr, hr, dhr, x, h, dh)
        x <- ins$x; h <- ins$h; dh <- ins$dh
        # Hulls changed: stop using this batch's (u_star, l_star).
        break
      }
    }

    for (s in which(accept)) {
      if (n_accept >= n) break
      n_accept <- n_accept + 1L
      samples[n_accept] <- x_star[s]
    }
  }
  samples
}

# ---------------------------------------------------------------------------
# 6. Formal testing against known truth
# ---------------------------------------------------------------------------

# Kolmogorov-Smirnov helper: compares empirical CDF of samples to a reference
# sampler (draws from the true distribution). Deterministic given `seed`.
.ars_ks_check <- function(samples, ref_sampler, seed = 12345) {
  set.seed(seed)
  ref <- ref_sampler(length(samples))
  suppressWarnings(ks.test(samples, ref)$p.value)
}

# One-line reporter in the required format, with mean/sd statistics.
.ars_report <- function(test_name, passed, detail = "") {
  status <- if (isTRUE(passed)) "PASS" else "FAIL"
  msg <- sprintf("%s: %s", test_name, status)
  if (nzchar(detail)) msg <- paste0(msg, " | ", detail)
  cat(msg, "\n")
  isTRUE(passed)
}

#' Formal tests for the adaptive rejection sampler
#'
#' Compares \code{ars} output against known truth (true moments and a
#' Kolmogorov-Smirnov comparison with direct samplers), checks input
#' validation, and checks that non-log-concave densities raise an error.
#' All sampling tests use fixed seeds so results are reproducible.
#'
#' @return Invisibly, TRUE if every test passed, FALSE otherwise.
#' @export
test <- function() {
  cat("Running ARS formal tests (seeded; stochastic checks use tolerances)...\n")
  results <- c()

  stat_str <- function(s) sprintf("mean=%.3f sd=%.3f", mean(s), sd(s))

  # -- Test 1: standard normal ------------------------------------------------
  set.seed(42)
  s_norm <- ars(2000, function(x) dnorm(x))
  p_norm <- .ars_ks_check(s_norm, function(m) rnorm(m))
  ok_norm <- abs(mean(s_norm) - 0) < 0.15 && abs(sd(s_norm) - 1) < 0.15 && p_norm > 0.01
  results["normal"] <- .ars_report("NORMAL",
    ok_norm, sprintf("%s true_mean=0.000 true_sd=1.000 ks_p=%.3f", stat_str(s_norm), p_norm))

  # -- Test 2: exponential(1) on (0, Inf) ------------------------------------
  set.seed(43)
  s_exp <- ars(2000, function(x) dexp(x, rate = 1), a = 0)
  p_exp <- .ars_ks_check(s_exp, function(m) rexp(m, rate = 1))
  ok_exp <- abs(mean(s_exp) - 1) < 0.15 && abs(sd(s_exp) - 1) < 0.2 && p_exp > 0.01
  results["exponential"] <- .ars_report("EXPONENTIAL",
    ok_exp, sprintf("%s true_mean=1.000 true_sd=1.000 ks_p=%.3f", stat_str(s_exp), p_exp))

  # -- Test 3: Gamma(2, 1) is log-concave (shape >= 1) ------------------------
  set.seed(44)
  s_gamma <- ars(2000, function(x) dgamma(x, shape = 2, rate = 1), a = 0)
  p_gamma <- .ars_ks_check(s_gamma, function(m) rgamma(m, shape = 2, rate = 1))
  ok_gamma <- abs(mean(s_gamma) - 2) < 0.25 && abs(sd(s_gamma) - sqrt(2)) < 0.25 && p_gamma > 0.01
  results["gamma_shape2"] <- .ars_report("GAMMA_SHAPE2",
    ok_gamma, sprintf("%s true_mean=2.000 true_sd=1.414 ks_p=%.3f", stat_str(s_gamma), p_gamma))

  # -- Test 4: uniform masses only on [2, 5] via a/b bounds ------------------
  set.seed(45)
  s_unif <- ars(1000, function(x) dunif(x, min = 2, max = 5), a = 2, b = 5)
  ok_unif <- all(s_unif >= 2 & s_unif <= 5) &&
    abs(mean(s_unif) - 3.5) < 0.2 && abs(sd(s_unif) - sqrt(9 / 12)) < 0.2
  results["truncated_uniform"] <- .ars_report("TRUNCATED_UNIFORM",
    ok_unif, sprintf("%s true_mean=3.500 true_sd=0.866 range=[%.3f,%.3f]",
                     stat_str(s_unif), min(s_unif), max(s_unif)))

  # -- Test 5: unnormalized density (scaled normal) ----------------------------
  set.seed(46)
  s_unnorm <- ars(1500, function(x) 7.3 * dnorm(x, mean = 1, sd = 2))
  p_unnorm <- .ars_ks_check(s_unnorm, function(m) rnorm(m, mean = 1, sd = 2))
  ok_unnorm <- abs(mean(s_unnorm) - 1) < 0.3 && abs(sd(s_unnorm) - 2) < 0.3 && p_unnorm > 0.01
  results["unnormalized"] <- .ars_report("UNNORMALIZED",
    ok_unnorm, sprintf("%s true_mean=1.000 true_sd=2.000 ks_p=%.3f", stat_str(s_unnorm), p_unnorm))

  # -- Test 6: input validation ------------------------------------------------
  expect_error <- function(expr_desc, expr) {
    ok <- inherits(tryCatch({ expr; NULL }, error = function(e) e), "error")
    .ars_report(expr_desc, ok, if (ok) "correctly raised an error" else "NO error raised")
  }
  results["reject_negative_n"] <- expect_error("REJECT_NEGATIVE_N", ars(-5, function(x) dnorm(x)))
  results["reject_zero_n"] <- expect_error("REJECT_ZERO_N", ars(0, function(x) dnorm(x)))
  results["reject_noninteger_n"] <- expect_error("REJECT_NONINTEGER_N", ars(2.5, function(x) dnorm(x)))
  results["reject_nonfunction_g"] <- expect_error("REJECT_NONFUNCTION_G", ars(10, "dnorm"))
  results["reject_nonvectorized_g"] <- expect_error("REJECT_NONVECTORIZED_G", ars(10, function(x) 0.5))
  results["reject_bad_domain"] <- expect_error("REJECT_BAD_DOMAIN", ars(10, function(x) dnorm(x), a = 5, b = 2))
  results["reject_bad_x0"] <- expect_error("REJECT_BAD_X0", ars(10, function(x) dexp(x), a = 0, x0 = c(-1, 1)))

  # -- Test 7: non-log-concave density must be caught --------------------------
  # Cauchy (t_1) is not log-concave; Gamma(0.5) is not log-concave either.
  cauchy_err <- inherits(tryCatch({ set.seed(47); ars(200, function(x) dcauchy(x)) ; NULL },
    error = function(e) e), "error")
  results["nonlogconcave_cauchy"] <- .ars_report("NONLOGCONCAVE_CAUCHY",
    cauchy_err, if (cauchy_err) "correctly raised a log-concavity error" else "NO error raised")
  gamma_err <- inherits(tryCatch({ set.seed(48); ars(200, function(x) dgamma(x, shape = 0.5), a = 0) ; NULL },
    error = function(e) e), "error")
  results["nonlogconcave_gamma05"] <- .ars_report("NONLOGCONCAVE_GAMMA05",
    gamma_err, if (gamma_err) "correctly raised a log-concavity error" else "NO error raised")

  # -- Test 8: samples follow target shape (not uniform noise) -----------------
  set.seed(49)
  s_shape <- ars(2000, function(x) dnorm(x, mean = 5, sd = 0.5))
  p_unif <- suppressWarnings(ks.test(s_shape, "punif", min = min(s_shape), max = max(s_shape))$p.value)
  ok_shape <- abs(mean(s_shape) - 5) < 0.15 && p_unif < 0.01
  results["shape_not_uniform"] <- .ars_report("SHAPE_NOT_UNIFORM",
    ok_shape, sprintf("%s ks_vs_uniform_p=%.4f (small => not uniform)", stat_str(s_shape), p_unif))

  all_ok <- all(results)
  cat(sprintf("SUMMARY: %d/%d tests passed\n", sum(results), length(results)))
  invisible(all_ok)
}
